(function(root){
const maxBytes=2*1024*1024;
function checkTree(value,depth=0){if(depth>20)throw Error('Backup nesting is too deep.');if(value&&typeof value==='object'){for(const [key,v] of Object.entries(value)){if(['__proto__','constructor','prototype'].includes(key))throw Error('Backup contains an unsafe field.');checkTree(v,depth+1);}}}
function validateBackup(raw){const text=typeof raw==='string'?raw:JSON.stringify(raw);if(new TextEncoder().encode(text).length>maxBytes)throw Error('Backup must be smaller than 2 MB.');let data;try{data=JSON.parse(text);}catch{throw Error('Choose a valid JSON backup.');}checkTree(data);if(data?.app!=='worth-a-moment'||data.version!==1||!Array.isArray(data.reflections)||data.reflections.length>1000)throw Error('This is not a supported WAM decision backup.');const seen=new Set();for(const item of data.reflections){if(!item||typeof item!=='object'||typeof item.id!=='string'||!item.id||item.id.length>100||seen.has(item.id)||typeof item.task!=='string'||!item.task||item.task.length>160||typeof item.alt!=='string'||item.alt.length>160||typeof item.date!=='string'||!Number.isFinite(Date.parse(item.date)))throw Error('A decision record is missing valid identifying information.');seen.add(item.id);for(const key of ['profileSummary','next','actualReflection'])if(item[key]!==undefined&&(typeof item[key]!=='string'||item[key].length>50000))throw Error('A decision contains invalid reflection text.');if(item.personalScale!==undefined&&(!item.personalScale||typeof item.personalScale!=='object'||Array.isArray(item.personalScale)))throw Error('A decision has invalid scale information.');}
return data.reflections;}
function mergeReflections(existing,incoming){const ids=new Set(existing.map(item=>item.id));const added=incoming.filter(item=>!ids.has(item.id));if(existing.length+added.length>1000)throw Error('Restoring would exceed the 1,000-decision backup limit.');return {records:[...existing,...added],added:added.length,kept:incoming.length-added.length};}
if(typeof module==='object'&&module.exports)module.exports={validateBackup,mergeReflections};
if(!root.document)return;
const journal=document.getElementById('journal'),panel=document.createElement('details');panel.id='decisionBackups';const summary=document.createElement('summary');summary.textContent='Back up or restore your decisions';panel.append(summary);const help=document.createElement('p');help.className='helper';help.textContent='Download your saved decisions and their original score snapshots. Restore adds missing decisions and keeps existing ones when IDs match. Scale preferences and learned-model observations are not included. The file contains personal reflections; choose where you save it.';panel.append(help);const exportButton=document.createElement('button'),importButton=document.createElement('button'),picker=document.createElement('input'),status=document.createElement('p');exportButton.type=importButton.type='button';exportButton.className=importButton.className='quiet';exportButton.textContent='Download decision backup';importButton.textContent='Restore from backup';picker.type='file';picker.accept='.json,application/json';picker.hidden=true;picker.id='decisionBackupFile';status.id='backupStatus';status.className='helper';status.setAttribute('role','status');panel.append(exportButton,importButton,picker,status);journal.querySelector('h2').after(panel);
exportButton.onclick=()=>{try{const body=JSON.stringify({app:'worth-a-moment',version:1,createdAt:new Date().toISOString(),reflections:saved},null,2);validateBackup(body);const blob=new Blob([body],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='wam-decisions-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent=`Downloaded ${saved.length} saved decision${saved.length===1?'':'s'}.`;}catch(e){status.textContent=e.message;}};
importButton.onclick=()=>picker.click();picker.onchange=async()=>{const file=picker.files?.[0];if(!file)return;try{if(file.size>maxBytes)throw Error('Backup must be smaller than 2 MB.');const incoming=validateBackup(await file.text()),merged=mergeReflections(saved,incoming);localStorage.setItem('worth-reflections',JSON.stringify(merged.records));saved=merged.records;render();status.textContent=`Restored ${merged.added} decision${merged.added===1?'':'s'}; kept ${merged.kept} existing matches. Your existing decisions were not overwritten.`;}catch(e){status.textContent='Could not restore: '+e.message;}finally{picker.value='';}};
})(typeof globalThis!=='undefined'?globalThis:this);
